function progress(p){$('progress-text').textContent=p.totalPlans?`${p.plansEvaluated} / ${p.totalPlans} plans`:`${p.plansEvaluated} search nodes`;$('progress-value').style.strokeDashoffset=p.totalPlans?75.4*(1-p.plansEvaluated/p.totalPlans):37.7;}
function setBusy(value){busy=value;$('calculate').disabled=value;for(const id of ['calculate-credit','calculate-reach','calculate-fragility'])if($(id))$(id).disabled=value||(id==='calculate-credit'&&!state?.plan);$('cancel').hidden=!value;}
