  $('inspector-title').textContent=state.view==='manual'?'Your repair plan':'Plan inspector';if(!state.plan&&state.view!=='manual'){$('inspector-content').innerHTML=`<div class="eyebrow">MAKE A BETTER CONNECTION</div><h3>Choose a limit.<br>Find the leverage.</h3><p>Evaluate repair combinations and inspect the journeys they restore.</p><p>Start with Connected City for the synthetic demo. Delhi recorded evidence may have no compatible routes because missing tags remain unknown.</p>`;return;}
