function renderManual(){const p=state.manual||state.baseline,used=p?.totalCost||0,cap=state.useMoney?Number($('money-budget').value):Infinity,full=state.manualIds.length>=state.limit;$('manual-count').textContent=`${state.manualIds.length} / ${state.limit} repairs · ${money(used)}${state.useMoney?' / '+money(cap):''}`;$('manual-choices').innerHTML=state.data.repairs.map(r=>{const selected=state.manualIds.includes(r.id),resolved=r.resolvesBarrierIds.every(id=>state.data.barriers.find(b=>b.id===id).status==='resolved');return`<label class="repair-choice"><input data-manual="${esc(r.id)}" type="checkbox" ${selected?'checked':''} ${!selected&&(full||used+r.cost>cap||resolved)?'disabled':''}><span>${esc(r.title)}<small>${money(r.cost)} · ${resolved?'resolved':esc(r.provenance)}</small></span></label>`;}).join('')||'<p class="hint">No candidate repairs in this evidence dataset.</p>';for(const el of $('manual-choices').querySelectorAll('[data-manual]'))el.onchange=()=>manualToggle(el.dataset.manual,el.checked);const optimal=state.plan?.recommended;$('comparison').innerHTML=`<div class="comparison"><div><span>Your plan</span><strong>+${p?.newlyConnectedJourneyIds.length||0}</strong><small>${money(used)}</small></div><div><span>Recommended</span><strong>${optimal?'+'+optimal.newlyConnectedJourneyIds.length:'—'}</strong><small>${optimal?money(optimal.totalCost):'Calculate first'}</small></div></div><p class="hint">Same repair and money limits. Counts measure destination pairs, not people.</p>`;$('greedy').textContent=state.plan?`Greedy baseline: ${state.plan.greedy.newlyConnectedJourneyIds.length} pairs. ${state.plan.optimal?'Optimal':'Best found'}: ${optimal.newlyConnectedJourneyIds.length}. Greedy only takes a repair with an immediate gain; complementary repairs can defeat it.`:'';}
